from lib import *
recs=[
R(6990463,"ग्लूटेन-मुक्त इंग्लिश मफ़िन","ग्लूटेन-मुक्त इंग्लिश मफ़िन की पोषण संबंधी जानकारी","1","1 साबुत मफ़िन",["1 साबुत ग्लूटेन-मुक्त इंग्लिश मफ़िन"],[]),
R(6991688,"सौते की हुई हरी सब्ज़ियों के साथ पोच्ड अंडे",
"यह रंगीन नाश्ता आपके दिन की सेहतमंद शुरुआत का एक तरीक़ा है! मिली-जुली हरी पत्तेदार सब्ज़ियाँ फ़ाइबर और पोषक तत्व देती हैं, जिससे मधुमेह के अनुकूल ऐसा भोजन बनता है जिसे खाकर आपको अच्छा लगेगा।",
"2","1/2 हरी सब्ज़ियाँ + 1 अंडा + 1/2 स्लाइस टोस्ट",
["1 बड़ा चम्मच सफ़ेद सिरका","2 बड़े अंडे","1 बड़ा चम्मच कैनोला तेल","1 छोटा प्याज़ (बारीक कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","4 कप मिली-जुली हरी पत्तेदार सब्ज़ियाँ (जैसे पालक, केल, स्विस चार्ड; कटी हुई)","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च","2 स्लाइस साबुत अनाज की ब्रेड (टोस्ट की हुई, आधी कटी हुई)"],
["एक चौड़े, उथले पैन में पानी भरें और उसे हल्के उबाल पर लाएँ। पानी में थोड़ा-सा सिरका डालें।","हर अंडे को एक छोटे कटोरे में तोड़ें।","हर अंडे को एक-एक करके उबलते पानी में सावधानी से सरकाएँ। पीली जर्दी बहती हुई रखने के लिए 3–4 मिनट पोच करें, या जर्दी ज़्यादा सख़्त चाहिए तो और देर तक।","जब अंडे पोच हो रहे हों, तब एक अलग कड़ाही में मध्यम आँच पर तेल गरम करें।","कटा हुआ प्याज़ डालें और नरम होने तक, लगभग 5 मिनट, पकाएँ।","बारीक कटा लहसुन डालकर चलाएँ और 30 सेकंड और पकाएँ।","कटी हुई मिली-जुली हरी सब्ज़ियाँ कड़ाही में डालें और मुरझाने तक भूनें।","हरी सब्ज़ियों में नमक और काली मिर्च डालें।","पोच्ड अंडों को छेद वाले चम्मच से पानी से निकालें और अतिरिक्त पानी सोखने के लिए पेपर टॉवल बिछी प्लेट पर रखें।","पोच्ड अंडों को सौते की हुई हरी सब्ज़ियों की परत पर परोसें और किनारे साबुत अनाज की ब्रेड रखें।"]),
R(6991775,"चटपटी ब्रोकोलिनी और लहसुन",
"ब्रोकोलिनी स्वाद और बनावट में ब्रोकोली जैसी होती है, लेकिन इसके डंठल लंबे और पतले होते हैं और फूल छोटे होते हैं। यह सरल, स्वादिष्ट रेसिपी ब्रोकोलिनी तैयार करने का तेज़ और आसान तरीक़ा है। आप इसे उतने ही समय में तैयार कर सकते हैं जितना आपके मुख्य व्यंजन को पकाने में लगता है। अगर आपको ब्रोकोलिनी न मिले, तो आप आसानी से उसकी जगह ब्रोकोली इस्तेमाल कर सकते हैं।",
"8","1/2 कप",
["1 बड़ा चम्मच जैतून का तेल","4 कली लहसुन (पतली कटी हुई)","2 पाउंड ब्रोकोलिनी (डंठल छँटे हुए)","1/4 कप कम सोडियम वाला सब्ज़ी का ब्रोथ","1 चुटकी कुटी हुई लाल मिर्च के गुच्छे","1 1/2 बड़े चम्मच नीबू का रस","2 छोटे चम्मच ताज़ा नीबू का ज़ेस्ट (छिलका)"],
["तेल को मध्यम-धीमी आँच पर गरम करें। लहसुन डालें और लगभग 5 से 6 मिनट, या बस लहसुन के भूरा होना शुरू होने तक, भूनें।","ब्रोकोलिनी, ब्रोथ और कुटी हुई लाल मिर्च डालें। पैन को ढकें और मध्यम-तेज़ आँच पर भाप में तब तक पकने दें जब तक ब्रोकोलिनी चटक हरी और नरम न हो जाए, लगभग 5 से 6 मिनट।","नीबू का रस और ज़ेस्ट डालें, और तुरंत परोसें।"]),
R(6992159,"भूमध्यसागरीय चिकन पिटा",
"बचे हुए चिकन का इस सरल और स्वादिष्ट सैंडविच में नया उपयोग करें! यह घर से काम करते समय दोपहर के लिए झटपट और आसान भोजन, या व्यस्त हफ़्ते के दिन के रात के खाने के लिए एकदम सही है। अगर आपके पास ज़ात्ज़िकी सॉस नहीं है, तो आप उसकी जगह सादा ग्रीक योगर्ट इस्तेमाल कर सकते हैं। डबल अप: और भी ज़्यादा स्वाद के लिए हमारी ग्रीक योगर्ट में मैरिनेट किए चिकन की रेसिपी से बचे हुए चिकन का उपयोग करें!",
"4","1 पिटा पॉकेट (जिसमें 1/2 पिटा ब्रेड, 2 1/2 औंस चिकन, 2 बड़े चम्मच सॉस, 1/2 कप सब्ज़ियाँ और 2 बड़े चम्मच बादाम शामिल हैं)",
["2 कप पका हुआ चिकन (टुकड़ों में कटा हुआ)","1/2 कप कम वसा वाली ज़ात्ज़िकी सॉस (या वसा-रहित सादा ग्रीक योगर्ट)","2 साबुत साबुत अनाज के पॉकेट-शैली वाले पिटा (4 पिटा पॉकेट बनाने के लिए आधे कटे हुए)","1 कप खीरा (छोटे टुकड़ों में कटा हुआ)","1 कप टमाटर (छोटे टुकड़ों में कटे हुए)","1/2 कप ड्राई-रोस्टेड बादाम (बिना नमक के, स्लाइस किए हुए)"],
["एक मध्यम मिक्सिंग कटोरे में चिकन और ज़ात्ज़िकी सॉस को मिलाएँ। हर पिटा पॉकेट में चिकन के मिश्रण का ½ कप भरें।","हर भरे हुए पिटा पॉकेट के ऊपर ¼ कप खीरा, ¼ कप टमाटर और 2 बड़े चम्मच कटे हुए बादाम डालें।"]),
R(6992179,"परमेज़ान क्रस्टेड चिकन",
"यह स्वादिष्ट और बहुमुखी चिकन रेसिपी है, इसे सब्ज़ियों के साथ मुख्य व्यंजन के रूप में या सलाद पर परोसें। यह बच्चों को भी पसंद आने वाली है और किसी भी जमे हुए चिकन नगेट से कहीं ज़्यादा सेहतमंद है।",
"6","2 चिकन स्ट्रिप्स",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/2 कप कॉर्नमील","1/3 कप परमेज़ान चीज़ (ताज़ा कद्दूकस की हुई)","1/2 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच काली मिर्च","3 बड़े अंडों की सफ़ेदी","1 1/2 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (12 पतली पट्टियों में कटे हुए)"],
["ओवन को 425 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर कुकिंग स्प्रे करें।","एक उथली डिश में कॉर्नमील, परमेज़ान चीज़, लहसुन पाउडर और काली मिर्च मिलाएँ।","एक दूसरी उथली बेकिंग डिश में अंडे की सफ़ेदी को फेंटें।","चिकन ब्रेस्ट की पट्टी को अंडे के मिश्रण में डुबोएँ और फिर कॉर्नमील के मिश्रण में अच्छी तरह लपेटें। अच्छी तरह परत चढ़ाएँ और बेकिंग शीट पर रखें। सभी चिकन की पट्टियों के लिए यही प्रक्रिया दोहराएँ।","चिकन की पट्टियों पर कुकिंग स्प्रे करें। 15-20 मिनट या पकने तक बेक करें; पकाने के आधे समय पर चिकन के टुकड़ों को पलट दें।"]),
R(6992930,"पेस्टो डेविल्ड एग्स",
"पेस्टो डेविल्ड एग्स क्लासिक रेसिपी का एक स्वादिष्ट और सुरुचिपूर्ण रूप हैं। पेस्टो, मेयोनीज़ और डिजॉन सरसों का मेल एक मलाईदार और तीखा भरावन बनाता है जो उबले अंडों की क़ुदरती भरपूरी के साथ बेहतरीन लगता है। ये डेविल्ड एग्स पार्टियों के लिए बढ़िया एपेटाइज़र हैं या आपके ब्रंच के भोजन में एक स्वादिष्ट जोड़।",
"8","2 आधे भाग",
["8 बड़े अंडे","1/4 कप लाइट मेयोनीज़","2 बड़े चम्मच जार वाली पेस्टो सॉस","1 छोटा चम्मच डिजॉन सरसों","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["अंडों को सॉसपैन में एक परत में रखें और पानी से ढक दें। पानी को उबाल आने तक गरम करें, फिर आँच को धीमा करें, ढकें और 10–12 मिनट धीमी आँच पर पकाएँ।","उबले हुए अंडों को ठंडा करने के लिए बर्फ़ के पानी के बर्तन में डालें।","जब अंडे ठंडे हो जाएँ, तो उनके छिलके उतारें और उन्हें लंबाई में आधा काटें। जर्दी निकालकर एक कटोरे में रखें।","अंडे की जर्दी वाले कटोरे में मेयोनीज़, तैयार बेसिल पेस्टो, डिजॉन सरसों, नमक और काली मिर्च डालें। सामग्री को चिकना होने तक मसलकर मिलाएँ।","पेस्टो के भरावन को खोखले किए गए अंडे के सफ़ेद हिस्सों में चम्मच से या पाइपिंग बैग से भरें।","परोसने से पहले डेविल्ड एग्स को कम से कम 30 मिनट फ़्रिज में ठंडा करें।"]),
R(6993572,"अंडे का सूफ़ले",
"यह सब्ज़ियों के साथ बना हल्का और फूला हुआ अंडे का सूफ़ले है।",
"4","सूफ़ले का ¼ भाग",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 कप ताज़ी केल (कटी हुई)","1/2 छोटा प्याज़ (पतला कटा हुआ)","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/2 छोटा चम्मच हर्ब्स द प्रोवांस","1 कप पके हुए टर्की सॉसेज का चूरा","1 कप अंडे का विकल्प","4 बड़े अंडों की सफ़ेदी","1/2 छोटा चम्मच क्रीम ऑफ़ टार्टर"],
["ओवन को 375 डिग्री F पर पहले से गरम करें।","एक सौते पैन पर कुकिंग स्प्रे लगाकर मध्यम आँच पर रखें। केल और प्याज़ को तब तक भूनें जब तक प्याज़ बस पूरी तरह पक न जाए, लगभग 5-6 मिनट। नमक (वैकल्पिक), हर्ब्स द प्रोवांस और टर्की सॉसेज डालें। ठंडा होने के लिए एक तरफ़ रख दें।","जब सब्ज़ियाँ और माँस ठंडे हो जाएँ, तो अंडे का विकल्प मिलाएँ और एक तरफ़ रख दें।","एक साफ़ कटोरे में अंडे की सफ़ेदी और क्रीम ऑफ़ टार्टर मिलाएँ। इलेक्ट्रिक मिक्सर से अंडे की सफ़ेदी को कड़े शिखर बनने तक फेंटें।","अंडे की सफ़ेदी को अंडे और सब्ज़ियों के मिश्रण में हल्के हाथ से मिलाएँ, और 2 1/2 क्वार्ट की गोल बेकिंग डिश में डालें। (आप 8 इंच की चौकोर डिश भी इस्तेमाल कर सकते हैं। ध्यान रखें कि बेकिंग डिश पर कुकिंग स्प्रे न लगाएँ वरना सूफ़ले फूलेगा नहीं।)","30 मिनट बेक करें। सूफ़ले को चार बराबर टुकड़ों में काटें और तुरंत परोसें।","ध्यान दें: ओवन से निकालने के बाद सूफ़ले थोड़ा बैठ जाएगा, यह सामान्य है।"]),
R(6994119,"कुरकुरी मक्का सालसा और अरुगुला के साथ ग्रिल्ड तिलापिया",
"यह ग्रिल्ड तिलापिया एक ताज़ा और स्वादिष्ट व्यंजन है जो कम वसा और कम कार्बोहाइड्रेट वाले खान-पान के पैटर्न में फ़िट बैठता है। नरम तिलापिया फ़िलेट को बिल्कुल सही तरह ग्रिल किया जाता है और कुरकुरी मक्का, टमाटर, प्याज़ और हरे धनिये से बनी रंगीन सालसा के साथ, तीखे अरुगुला की परत पर परोसा जाता है।",
"4","4 औंस तिलापिया, ¾ कप सालसा, 1 कप अरुगुला",
["2 कप ताज़े या जमे हुए मक्का के दाने (अगर जमे हैं तो पिघलाए हुए)","1 मध्यम लाल शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","1/2 छोटा लाल प्याज़ (बारीक कटा हुआ)","1 छोटी जलापेन्यो मिर्च (बारीक कटी हुई)","2 बड़े चम्मच बिना मसाले वाला राइस विनेगर","1 बड़ा चम्मच जैतून का तेल","1/4 कप ताज़ा हरा धनिया (कटा हुआ)","4 फ़िलेट (हर एक 4–5 औंस) तिलापिया (ताज़ा या जमी हुई, पिघलाई हुई)","1 नॉनस्टिक कुकिंग स्प्रे","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच स्मोक्ड पैप्रिका","1/4 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच काली मिर्च","4 कप बेबी अरुगुला"],
["एक बड़े कटोरे में मक्का, लाल शिमला मिर्च, लाल प्याज़, जलापेन्यो, राइस विनेगर, जैतून का तेल और हरा धनिया मिलाएँ। अच्छी तरह मिलाकर एक तरफ़ रख दें।","तिलापिया फ़िलेट को पेपर टॉवल से थपथपाकर सुखाएँ। दोनों तरफ़ कुकिंग स्प्रे करें। उन पर जीरा, स्मोक्ड पैप्रिका, लहसुन पाउडर और काली मिर्च बराबर छिड़कें।","ग्रिल या ग्रिल पैन को मध्यम-तेज़ आँच पर पहले से गरम करें। पैन पर तेल का स्प्रे करें। तिलापिया को हर तरफ़ 3–4 मिनट ग्रिल करें, या जब तक मछली काँटे से आसानी से अलग-अलग न हो जाए। आँच से हटाएँ और एक मिनट आराम करने दें।","अरुगुला को 4 प्लेटों में बाँटें। हर अरुगुला की परत पर एक ग्रिल्ड तिलापिया फ़िलेट रखें। कुरकुरी मक्का सालसा को मछली के ऊपर और आसपास चम्मच से डालें।"]),
R(6994243,"बेक्ड ब्लूबेरी बादाम ओटमील",
"जई, चिया, अलसी और हेम्प के बीजों से बना एक पौष्टिक बेक्ड ओटमील, जिसमें ब्लूबेरी मिलाई जाती हैं और ऊपर वसा-रहित ग्रीक योगर्ट और भुने हुए बादाम डाले जाते हैं। फ़ाइबर और प्रोटीन से भरपूर यह नाश्ता दिल के लिए फ़ायदेमंद वसा के साथ संतुलित पोषण देता है और इसमें कोई अतिरिक्त चीनी नहीं है।",
"6","1.5\" x 5\" का टुकड़ा",
["6 बड़े चम्मच कतरे हुए बादाम","2 साबुत अंडे","1/2 कप बिना मीठा बादाम दूध","1 छोटा चम्मच वनीला एक्सट्रैक्ट","2 बड़े चम्मच चीनी-रहित ब्राउन शुगर विकल्प","1/4 कप चिया बीज","2 बड़े चम्मच पिसी अलसी","1/2 कप रोल्ड ओट्स","1/4 कप हेम्प हार्ट्स","1/4 कप बादाम का आटा","1 छोटा चम्मच पिसी दालचीनी","1 छोटा चम्मच बेकिंग पाउडर","1/8 छोटा चम्मच नमक","3/4 कप Dole® ब्लूबेरी","1 1/2 कप वसा-रहित सादा ग्रीक योगर्ट"],
["ओवन को 350 डिग्री F (175 डिग्री C) पर पहले से गरम करें। 9x5 इंच के लोफ़ पैन पर चिकनाई लगाएँ या उसमें लाइनर लगाएँ।","बादाम को किनारों वाली बेकिंग शीट पर फैलाएँ। ओवन में 5–8 मिनट तक हल्का भूरा और सुगंधित होने तक भूनें।","एक मध्यम कटोरे में अंडे, बादाम दूध, वनीला और चीनी-रहित ब्राउन शुगर विकल्प को चिकना और मलाईदार होने तक फेंटें।","एक बड़े कटोरे में चिया बीज, अलसी, रोल्ड ओट्स, हेम्प हार्ट्स, बादाम का आटा, दालचीनी, बेकिंग पाउडर और नमक मिलाएँ।","गीला मिश्रण सूखी सामग्री में डालें और पूरी तरह मिलने तक चलाएँ। घोल थोड़ा गाढ़ा हो जाएगा क्योंकि चिया और अलसी के बीज तरल को सोख लेंगे।","ब्लूबेरी को हल्के हाथ से मिलाएँ।","मिश्रण को तैयार लोफ़ पैन में बराबर फैलाएँ। 30–35 मिनट बेक करें, बीच में पैन को घुमा दें, जब तक बीच का हिस्सा जम न जाए और ऊपर हल्का सुनहरा होकर फटना शुरू न हो जाए।","ओटमील को 6 बराबर हिस्सों में काटने से पहले 10 मिनट ठंडा होने दें। हर सर्विंग पर ¼ कप कम वसा वाला ग्रीक योगर्ट और 1 बड़ा चम्मच कतरे हुए बादाम डालकर गरम परोसें। ठंडे हुए बचे हुए ओटमील को लपेटकर फ़्रिज में रखें।"]),
R(6994909,"चिकन नाचो कैसरोल",
"यह कम वसा वाला चिकन नाचो कैसरोल चिकन, बीन्स, सब्ज़ियों और तीखे मसालों से बना एक गरम, आरामदायक व्यंजन है। इसमें नाचोज़ के सारे स्वाद एक ही आसान भोजन में बेक किए गए हैं। इसे तैयार करना आसान है और यह पेट भरने वाले, परिवार को पसंद आने वाले रात के खाने के लिए बढ़िया है।",
"6","1 कप",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/8 छोटा चम्मच काली मिर्च","1 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (छोटे टुकड़ों में कटे हुए)","1 (14.5 औंस) कैन फ़ायर-रोस्टेड टमाटर","1 (15 औंस) कैन बिना नमक मिलाई काली बीन्स (पानी निथारी और धोई हुई)","2 छोटे चम्मच चिली पाउडर","1/2 छोटा चम्मच जीरा","1/2 छोटा चम्मच लहसुन पाउडर","2/3 कप चेडर चीज़ (कद्दूकस किया हुआ, कम वसा वाला)","1 1/2 औंस टॉर्टिला चिप्स (लगभग 24 चिप्स, कुचले हुए)"],
["ओवन को 375 डिग्री F पर पहले से गरम करें। 2 ½ क्वार्ट की बेकिंग डिश पर कुकिंग स्प्रे करें।","चिकन पर काली मिर्च छिड़कें। एक बड़े सौते पैन पर कुकिंग स्प्रे करें और उसे मध्यम-तेज़ आँच पर गरम करें। चिकन डालें और 8 मिनट पकाएँ।","पैन में कटे हुए टमाटर, काली बीन्स, चिली पाउडर, जीरा और लहसुन पाउडर डालें। आँच को धीमा करें और 5 मिनट धीमी आँच पर पकाएँ।","चिकन का मिश्रण बेकिंग डिश में डालें। ऊपर से चीज़ छिड़कें और फिर कुचले हुए टॉर्टिला चिप्स डालें। 12 मिनट या चीज़ के पिघलने तक बेक करें।"]),
R(6995196,"खीरा-नीबू का पानी",
"पानी में फलों और जड़ी-बूटियों का रस घोलकर उसे और स्वादिष्ट बनाएँ! खीरे के स्लाइस, नीबू और ताज़ी जड़ी-बूटियाँ डालने से सादे पानी में बिना किसी चीनी या कैलोरी के हल्का स्वाद आ जाता है। तरबूज़ और रोज़मेरी, अनानास और पुदीना जैसे दूसरे संयोजन भी आज़माएँ, या जो भी आपके मन में आए!",
"10","1 कप (8 औंस)",
["1 मध्यम खीरा","1 नीबू","1/4 कप ताज़ी तुलसी की पत्तियाँ","1/4 कप ताज़ी पुदीने की पत्तियाँ","10 कप (80 औंस) पानी"],
["खीरे और नीबू को पतले स्लाइस में काटकर एक बड़े जग में डालें।","तुलसी और पुदीने की पत्तियों को हाथ से हल्का कुचलकर जग में डालें। ऊपर से 10 कप पानी डालें।","स्वादों को पूरी तरह घुलने देने के लिए परोसने से पहले पानी को रात भर फ़्रिज में रखें।"]),
R(6996404,"बादाम बटर","1 बड़े चम्मच बादाम बटर की पोषण संबंधी जानकारी","1","1 बड़ा चम्मच",["1 बड़ा चम्मच बादाम बटर"],[]),
R(6999413,"पेस्टो सॉस के साथ सियर्ड ट्यूना",
"पेस्टो सॉस के साथ यह सियर्ड ट्यूना एक झटपट, स्वादिष्ट भोजन है जो ख़ास लगता है लेकिन बनाने में आसान है। ट्यूना कुछ ही मिनटों में पक जाती है और ताज़ा, जड़ी-बूटियों वाले पेस्टो के साथ अच्छी लगती है। यह उच्च प्रोटीन, कम कार्बोहाइड्रेट वाले ऐसे व्यंजन का आनंद लेने का सरल तरीक़ा है जो हल्का, संतोषजनक और ताज़ा स्वादों से भरपूर है। संतुलित भोजन के लिए इसे अपनी पसंद की स्टार्च-रहित सब्ज़ियों और साबुत अनाज के साथ परोसें।",
"4","1 ट्यूना फ़िलेट",
["1 बड़ा चम्मच जैतून का तेल","1 पाउंड अही ट्यूना फ़िलेट (4, 4-औंस के हिस्सों में बँटे हुए)","4 बड़े चम्मच जार वाली पेस्टो सॉस"],
["एक कड़ाही में मध्यम-तेज़ आँच पर जैतून का तेल गरम करें।","ट्यूना फ़िलेट को गरम तेल में रखें और एक तरफ़ 3-4 मिनट सेकें। ट्यूना को पलटें और हर फ़िलेट पर 1 बड़ा चम्मच पेस्टो सॉस लगाएँ। 3-4 मिनट और पकाएँ।"]),
]
save(5,recs)
